function eval_async(code, codeFile, tag)
%EVAL_ASYNC Run arbitrary MATLAB code as an asynchronous batch job.
%   code:     MATLAB statements executed as the body of an auto-generated
%             function `out = <snippet>(params)`. Assign `out` in the code to
%             export results (saved to the job dir as result.mat). For
%             multi-line code replace every line break with the token @@NL@@
%             (see mcp_code_arg), or prefer codeFile.
%   codeFile: absolute path to a UTF-8 text file holding the code; takes
%             precedence over code when non-empty.
%   tag:      free-text label, or '' for none.
%   The call prints a jobId immediately; poll with job_status. Use for any
%   evaluation expected to run longer than a few seconds. Snippet files
%   auto-delete after 7 days.
%   Returns no output argument on purpose: the server evaluates the tool call
%   as an expression, so a returned value was echoed as a stray `ans` block on
%   top of the formatted summary.

if nargin < 1, code = ''; end
if nargin < 2, codeFile = ''; end
if nargin < 3, tag = ''; end
code = mcp_code_arg(code, 'eval_async');
codeFile = mcp_str(codeFile);
tag = mcp_str(tag);
if ~isempty(codeFile)
    if ~exist(codeFile, 'file')
        error('eval_async:fileNotFound', '[eval_async:fileNotFound] codeFile not found: %s', codeFile);
    end
    fid = fopen(codeFile, 'r', 'n', 'UTF-8');
    if fid < 0
        error('eval_async:readFailed', '[eval_async:readFailed] Cannot read codeFile: %s', codeFile);
    end
    cr = onCleanup(@() mcp_fclose_quiet(fid));
    code = char(fread(fid, '*char').');
    fclose(fid);
    cr = []; %#ok<NASGU> % destroy the onCleanup so it will not close again
end
if isempty(code)
    error('eval_async:badArgs', '[eval_async:badArgs] Provide a non-empty code string or codeFile path');
end
snipDir = fullfile(mcp_ext_root(), 'snippets');
if ~exist(snipDir, 'dir')
    mkdir(snipDir);
end
% Sweep snippet files older than 7 days to keep the folder bounded.
old = dir(fullfile(snipDir, 'mcp_evalsnip_*.m'));
cutoff = datetime('now') - caldays(7);
for k = 1:numel(old)
    if datetime(old(k).date) < cutoff
        delete(fullfile(old(k).folder, old(k).name));
    end
end
fnName = ['mcp_evalsnip_' char(datetime('now', 'Format', 'HHmmssSSS')) '_' num2str(randi(899999) + 100000)];
fnPath = fullfile(snipDir, [fnName '.m']);
fid = fopen(fnPath, 'w');
if fid < 0
    error('eval_async:writeFailed', '[eval_async:writeFailed] Cannot create snippet file: %s', fnPath);
end
cleanup = onCleanup(@() mcp_fclose_quiet(fid));
fprintf(fid, 'function out = %s(params)\n', fnName);
fprintf(fid, '%%#ok<*NASGU,*UNRCH> %% Auto-generated by eval_async, do not edit.\n');
fprintf(fid, 'if nargin < 1, params = []; end\n');
fprintf(fid, 'out = [];\n');
fwrite(fid, newline);
fwrite(fid, code);
fwrite(fid, newline);
fclose(fid);
cleanup = []; %#ok<NASGU> % destroy the onCleanup so it will not close again
mcp_tool_log('eval_async', sprintf('code=%d chars codeFile=%s', numel(code), tern(isempty(codeFile),'yes','no')));
[jobId, state] = mcp_submit_job_core(fnPath, '', tag);
fprintf('jobId=%s\nstate=%s\njobDir=%s\n', jobId, state, fullfile(mcp_ext_root(), 'jobs', jobId));
fprintf('eval_async: snippet %s.m submitted (deleted automatically after 7 days)\n', fnName);
end

function out = tern(cond, a, b)
if cond, out = a; else, out = b; end
end

function mcp_fclose_quiet(fid)
try
    if fid > 0
        fclose(fid);
    end
catch
end
end
